"""Generate the database and Room lecture for the existing web deck."""

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "lectures" / "08-navigation-compose" / "slides.js"
slides = []


def section(title, subtitle):
    slides.append({"type": "section", "title": title, "subtitle": subtitle})


def slide(title, body, theory, badge=None):
    item = {"type": "content", "title": title,
            "body": body.replace("\\n", "\n"),
            "theory": theory.replace("\\n", "\n")}
    if title == "Gradle: зависимости":
        item["body"] = item["body"].replace(
            'ksp("androidx.room3:room3-compiler:$roomVersion")',
            'ksp("androidx.room3:room3-compiler:$roomVersion")\n'
            '    implementation("androidx.sqlite:sqlite-framework:2.7.1")',
        )
    if badge:
        item["badge"] = badge
    slides.append(item)


def visual(title, body, theory, image, caption):
    slide(title, body, theory)
    slides[-1].update({
        "image": image,
        "imageKind": "visual",
        "imageAlt": "Схема пересечения операций и категорий для " + title,
        "imageCaption": caption,
    })


def write_join_diagrams():
    """Draw two-set teaching diagrams for the four row-preserving joins."""
    for kind, label in (
        ("inner", "Совпавшие пары"),
        ("left", "Вся левая таблица"),
        ("right", "Вся правая таблица"),
        ("full", "Обе таблицы"),
    ):
        fills = {
            "inner": '<circle cx="350" cy="183" r="124" fill="#28b978" clip-path="url(#leftClip)"/>',
            "left": '<circle cx="244" cy="183" r="124" fill="#28b978"/>',
            "right": '<circle cx="350" cy="183" r="124" fill="#28b978"/>',
            "full": '<circle cx="244" cy="183" r="124" fill="#28b978"/><circle cx="350" cy="183" r="124" fill="#28b978" fill-opacity=".82"/>',
        }[kind]
        svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 360" role="img" aria-label="{label}">
<defs><clipPath id="leftClip"><circle cx="244" cy="183" r="124"/></clipPath></defs>
<rect width="600" height="360" rx="24" fill="#f7faf8"/>
<text x="300" y="37" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#17241d">{label}</text>
{fills}
<circle cx="244" cy="183" r="124" fill="none" stroke="#173b2a" stroke-width="4"/>
<circle cx="350" cy="183" r="124" fill="none" stroke="#173b2a" stroke-width="4"/>
<text x="173" y="185" text-anchor="middle" font-family="Arial, sans-serif" font-size="25" font-weight="700" fill="#10291b">A</text>
<text x="422" y="185" text-anchor="middle" font-family="Arial, sans-serif" font-size="25" font-weight="700" fill="#10291b">B</text>
<text x="244" y="333" text-anchor="middle" font-family="Arial, sans-serif" font-size="17" fill="#40564a">A: операции</text>
<text x="418" y="333" text-anchor="middle" font-family="Arial, sans-serif" font-size="17" fill="#40564a">B: категории</text>
</svg>'''
        (OUT.parent / f"join-{kind}.svg").write_text(svg, encoding="utf-8")


slides.append({
    "type": "title",
    "title": "Android-разработка",
    "subtitle": "Лекция 8. Базы данных и Room",
    "kicker": "08 / 15",
    "body": "92 слайда · FinanceApp · от модели данных до работающего локального хранилища",
    "theory": "### Цель занятия\nПосле лекции студент проектирует простую реляционную схему, пишет базовые SQL-запросы и создаёт локальную базу Android через Room 3.0.3. Пример продолжает FinanceApp лекции 7: история операций пока живёт только в ViewModel и исчезает после завершения процесса. На занятии мы последовательно переносим её в SQLite. Материал рассчитан на подробный теоретический доклад и может быть разбит на две пары.",
})

section("Зачем нужна база данных", "От состояния экрана к долговременным данным")
slide("Что происходит сейчас в FinanceApp", "- Транзакция добавляется в `MainUiState.transactions`.\\n- Поворот экрана может пережить ViewModel.\\n- Завершение процесса создаёт новую ViewModel с пустой историей.\\n- Баланс, вычисленный из памяти, также теряется.", "Покажите сценарий: добавить расход 250, принудительно остановить приложение, открыть снова. ViewModel сохраняется при конфигурационной пересоздаче, но не гарантирует сохранения после смерти процесса или перезапуска устройства. Это точная причина добавить постоянное локальное хранилище.")
slide("Где живут данные", "- Оперативная память: быстро, пока жив процесс.\\n- DataStore: небольшие настройки и предпочтения.\\n- Файлы: документы, изображения, произвольный поток байтов.\\n- SQLite/Room: структурированные записи и запросы.\\n- Сервер: обмен между устройствами и пользователями.", "Room хранит данные на устройстве и сам по себе не синхронизирует их между телефонами. Для истории расходов с фильтрами, сортировкой и связью с категориями реляционная база удобнее набора файлов. Настройки темы позже можно хранить в DataStore, это отдельная задача лекции 12.")
slide("Что такое база данных", "**База данных** — организованное долговременное множество связанных данных.\\n\\n**СУБД** управляет хранением, запросами, изменениями и целостностью.\\n\\nВ Android локальная реляционная СУБД — SQLite; Room работает поверх неё.", "Разведите понятия: база — конкретный набор таблиц и записей, СУБД — программный механизм, который читает и меняет этот набор. SQLite встроена в Android. Room является библиотекой доступа, а не новой СУБД: SQL и правила реляционной модели остаются важны.")
slide("Почему не список в JSON-файле", "- Чтобы найти расходы за месяц, пришлось бы читать и разбирать весь файл.\\n- При изменении одной записи пришлось бы переписывать файл.\\n- Связи и ограничения пришлось бы проверять вручную.\\n- SQL умеет фильтровать, агрегировать и сортировать рядом с данными.", "JSON-файл допустим для маленького документа, но при росте числа операций сложнее защищать данные от частичных изменений и держать связи корректными. Это сравнение не означает, что SQLite всегда быстрее в любом сценарии. Выбор зависит от структуры данных и нужных запросов.")
slide("Сценарий для сквозного примера", "Пользователь записывает операцию:\\n\\n`12.10 · Продукты · −850 ₽ · Категория «Еда»`\\n\\nНужно хранить описание, сумму, тип, дату и категорию, затем показывать историю и баланс после перезапуска.", "Дальше один и тот же набор данных пройдёт через проектирование таблиц, SQL и Room. В учебном примере сумма хранится в целых копейках как Long, чтобы не получать ошибки двоичной арифметики Double. Например, 850 рублей записываются как 85000 копеек.")
slide("Требования к хранилищу", "1. Добавить доход или расход.\\n2. Показать операции от новых к старым.\\n3. Найти операции конкретной категории.\\n4. Рассчитать баланс.\\n5. Сохранить историю при повторном запуске.", "Требования сначала формулируют в терминах действий пользователя, затем переводят в таблицы и запросы. Отдельно назовите ограничения: сумма строго положительна, описание не пустое, операция имеет устойчивый идентификатор. Эти правила частично проверяет UI, частично база.")

section("Реляционная модель", "Таблицы, строки, ключи и связи")
slide("Таблица, строка и столбец", "- `transactions` — таблица операций.\\n- Одна строка — одна операция.\\n- Столбец `amount_minor` — сумма в копейках.\\n- Схема задаёт допустимые столбцы и их типы.", "Реляционная таблица не является просто двумерной картинкой. У неё есть схема и ограничения. Порядок строк сам по себе не гарантирован, поэтому экран истории должен запрашивать явную сортировку `ORDER BY occurred_at DESC, id DESC`.")
slide("Проектируем строку операции", "Схема одной операции:\n\n```text\nid            41\ndescription   Продукты\namount_minor  85000\ntype          EXPENSE\noccurred_at   1791820800000\ncategory_id   3\n```\n\n`occurred_at` — время Unix в миллисекундах.", "Уточните единицы каждого числового поля. Дата как Long в миллисекундах удобна для сортировки и диапазонов, но временная зона важна при отображении и выборе границ календарного дня. `type` хранится строкой, чтобы значения были читаемы в инспекторе БД.")
slide("Первичный ключ", "`id` однозначно определяет строку.\\n\\n- У двух операций может совпадать сумма и описание.\\n- Время создания тоже не гарантирует уникальность.\\n- Автоматически генерируемый числовой `id` удобен для локальной БД.", "Первичный ключ запрещает двусмысленность при обновлении и удалении. Не выбирайте описание в качестве ключа: две покупки «Кофе» законны. Суррогатный Long id не несёт бизнес-смысла, но стабильно ссылается на запись.")
slide("Кандидатный и составной ключ", "- Кандидатный ключ — набор полей, способный однозначно определить строку.\\n- Первичный ключ выбирают из кандидатных.\\n- Составной ключ включает несколько столбцов.\\n- Например, в таблице связей `(transaction_id, tag_id)` пара уникальна.", "Составной ключ особенно понятен на таблице many-to-many: один тег можно привязать к разным операциям, одну операцию к разным тегам, но одинаковую пару повторять не нужно. В FinanceApp мы начинаем с одиночного id и позже возвращаемся к составному ключу.")
slide("Внешний ключ", "`transactions.category_id` указывает на `categories.id`.\\n\\nОн связывает операцию с существующей категорией и позволяет задать поведение при удалении категории.", "Внешний ключ защищает ссылочную целостность, если включён и объявлен в схеме. Он не означает, что Entity содержит объект Category как поле. В Room связи выражаются идентификаторами, SQL JOIN или отдельными объектами результата. Для категории можно выбрать `SET NULL`, `RESTRICT` или `CASCADE` в зависимости от бизнес-правила.")
slide("Связь один ко многим", "Одна категория «Еда» связана со многими расходами.\\n\\n`categories (1) ← transactions (много)`\\n\\nВ таблице операций хранится `category_id`, а название категории хранится один раз.", "Нарисуйте две строки операций с одинаковым category_id=3 и одну строку категории id=3. Это важный мост к нормализации: переименование «Еда» выполняется в одном месте, а не в каждой операции.")
slide("Связь многие ко многим", "Операция может иметь несколько тегов, тег может относиться к нескольким операциям.\\n\\nНужна таблица `transaction_tags(transaction_id, tag_id)` с составным ключом.", "Не помещайте список тегов через запятую в одно поле. Отдельная таблица связей позволяет искать операции по тегу, проверять существование обоих объектов и исключать дубли пары. Для базового FinanceApp теги необязательны, это расширение схемы.")
slide("NULL и отсутствие значения", "`category_id = NULL` может означать «категория не выбрана».\\n\\n`NULL` не равно пустой строке и не равно нулю.\\n\\nВ SQL проверка: `IS NULL`, а не `= NULL`.", "Трёхзначная логика SQL часто удивляет: сравнение с NULL даёт неизвестное значение. В Kotlin `Long?` хорошо отражает необязательный внешний ключ. Но нужно заранее решить, допустима ли операция без категории; это бизнес-решение, а не случайная техническая деталь.")
slide("Ограничения целостности", "- `PRIMARY KEY` — уникальная идентификация.\n- `NOT NULL` — значение обязательно.\n- `UNIQUE` — запрет повторов.\n- `FOREIGN KEY` — существующая связь.\n- `CHECK` — правило для значений строки.", "### Теоретическая сводка для преподавателя\n`CHECK` — ограничение целостности на уровне самой таблицы SQLite. В скобках записывается логическое выражение над значениями строки. При `INSERT` и `UPDATE` SQLite вычисляет его для каждой записываемой строки. Если результат равен нулю (ложь), операция завершается ошибкой и недопустимое значение не сохраняется. При обычном `SELECT` проверка не выполняется.\n\n### Пример из FinanceApp\n```sql\nCREATE TABLE transactions (\n    id INTEGER PRIMARY KEY,\n    amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),\n    type TEXT NOT NULL CHECK (type IN ('INCOME', 'EXPENSE'))\n);\n```\nСумма `25000` допустима, а `0` и `-500` нарушают первое правило. Значение `TRANSFER` нарушает второе. `CHECK` можно записать у конкретного столбца или на уровне таблицы, например `CHECK (end_at >= start_at)` для связи двух полей.\n\n### Тонкость с NULL\nВ SQLite `CHECK` отвергает только ложный результат. Если выражение даёт `NULL` (неизвестно), строка проходит проверку. Поэтому `CHECK (amount_minor > 0)` **не запрещает NULL**; для обязательного положительного числа нужны одновременно `NOT NULL` и `CHECK`. Это хороший пример того, почему ограничения дополняют друг друга.\n\n### Место в приложении\nПроверка ввода в Compose/ViewModel нужна для понятного сообщения пользователю. Ограничение в БД защищает данные независимо от того, какой код выполняет запись. Если SQLite отклонит запись, DAO получит ошибку ограничения; её нужно обработать. Само поле Entity или Kotlin `require` не добавляет `CHECK` в SQL-схему автоматически. Источник: [SQLite CREATE TABLE, раздел 3.7](https://www.sqlite.org/lang_createtable.html).")

section("SQL для приложения", "Чтение, запись и агрегация")
slide("Пять групп SQL-команд", """- **DDL** — Data Definition Language: структура БД.
- **DQL** — Data Query Language: чтение данных.
- **DML** — Data Manipulation Language: изменение строк.
- **DCL** — Data Control Language: права доступа.
- **TCL** — Transaction Control Language: транзакции.""", """Это распространённая учебная классификация команд SQL, а не отдельные режимы работы сервера. В некоторых источниках SELECT относят к DML, а DQL отдельно не выделяют. Для курса удобно различать пять вопросов: что хранится, что прочитать, что изменить, кому разрешить доступ и как объединить изменения в одну транзакцию. По мотивам [GeeksforGeeks](https://www.geeksforgeeks.org/sql/sql-ddl-dql-dml-dcl-tcl-commands/).""")
slide("DDL — Data Definition Language", """**Язык определения данных** меняет схему базы.

```sql
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);
ALTER TABLE categories ADD COLUMN color_argb INTEGER;
DROP TABLE old_categories;
```

В Room изменения DDL оформляют как миграцию схемы.""", """DDL работает с объектами базы, а не с отдельной строкой истории. `CREATE` создаёт таблицу или индекс, `ALTER` меняет существующую структуру, `DROP` удаляет объект. В учебных списках встречается `TRUNCATE`, но SQLite не поддерживает эту команду, поэтому не показываем её как рабочий пример для Android. В Room Entity описывает целевую схему, а переход между версиями базы должен быть миграцией. Источник: [SQLite CREATE TABLE](https://www.sqlite.org/lang_createtable.html).""")
slide("DQL — Data Query Language", """**Язык запросов к данным** возвращает результат без изменения таблиц.

```sql
SELECT description, amount_minor
FROM transactions
WHERE type = 'EXPENSE'
ORDER BY occurred_at DESC;
```

`FROM`, `WHERE` и `ORDER BY` — части команды `SELECT`.""", """SELECT возвращает ноль или больше строк. Уточните, что `FROM`, `WHERE`, `GROUP BY`, `HAVING` и `ORDER BY` называют частями запроса, а не самостоятельными командами DQL. В учебной классификации SELECT относится к DQL; в другой литературе DQL включают в DML. При работе с Room этот запрос попадёт в `@Query` и будет проверен при сборке. Источник: [SQLite SELECT](https://www.sqlite.org/lang_select.html).""")
slide("DML — Data Manipulation Language", """**Язык изменения данных** работает со строками таблиц.

- `INSERT` — добавить операцию.
- `UPDATE` — изменить описание или сумму.
- `DELETE` — удалить операцию.

`WHERE` в `UPDATE` и `DELETE` ограничивает затронутые строки.""", """DML меняет содержимое, не меняя структуру таблицы. На FinanceApp покажите разницу между `ALTER TABLE` (DDL, новая колонка) и `UPDATE transactions` (DML, новые значения в существующих строках). Запрос без WHERE затрагивает всю таблицу; это бывает намеренно, но в обычном редактировании одной операции опасно. В Room для типовых операций доступны `@Insert`, `@Update` и `@Delete`.""")
slide("DCL — Data Control Language", """**Язык управления доступом** задаёт права пользователей БД.

- `GRANT` — выдать право.
- `REVOKE` — отозвать право.

Это актуально для серверных СУБД. В локальном SQLite Android таких SQL-команд нет.""", """Пример для PostgreSQL: `GRANT SELECT ON transactions TO analyst;`. Так отдельному пользователю сервера разрешают чтение таблицы. В SQLite нет встроенных пользователей и модели `GRANT`/`REVOKE`; доступ к файлу базы на Android определяется изоляцией приложений и правами ОС. Поэтому слайд нужен для общей карты SQL, но выполнять эти команды в Room нельзя. Источник классификации: [GeeksforGeeks](https://www.geeksforgeeks.org/sql/sql-ddl-dql-dml-dcl-tcl-commands/).""")
slide("TCL — Transaction Control Language", """**Язык управления транзакциями** задаёт границу группы изменений.

```sql
BEGIN;
UPDATE accounts SET balance_minor = balance_minor - 500 WHERE id = 1;
UPDATE accounts SET balance_minor = balance_minor + 500 WHERE id = 2;
COMMIT;
```

При сбое до фиксации нужен `ROLLBACK`.""", """Транзакция гарантирует атомарность связанной группы изменений: оба баланса меняются вместе. `BEGIN` начинает явную транзакцию, `COMMIT` фиксирует её, `ROLLBACK` отменяет. `SAVEPOINT` создаёт промежуточную точку отката. В SQLite отдельные команды чтения или записи тоже выполняются внутри автоматически открываемой транзакции, но для нескольких связанных шагов нужна явная граница. В Room обычно используют `@Transaction` или API транзакций, а не отправляют BEGIN вручную. Источник: [SQLite Transaction](https://www.sqlite.org/lang_transaction.html).""")
slide("SQL и четыре базовых действия", "- `INSERT` создаёт строку.\\n- `SELECT` читает строки.\\n- `UPDATE` меняет существующие.\\n- `DELETE` удаляет.\\n\\nЭти действия часто объединяют словом CRUD.", "Room генерирует часть SQL за нас по аннотациям Insert, Update и Delete, но запросы для чтения мы пишем явно. Студенту нужно понимать SQL, иначе невозможно корректно фильтровать, объединять и агрегировать данные.")
slide("Создание таблиц в SQL", "```sql\\nCREATE TABLE categories (\\n  id INTEGER PRIMARY KEY,\\n  name TEXT NOT NULL UNIQUE\\n);\\nCREATE TABLE transactions (\\n  id INTEGER PRIMARY KEY,\\n  description TEXT NOT NULL,\\n  amount_minor INTEGER NOT NULL,\\n  category_id INTEGER,\\n  FOREIGN KEY (category_id) REFERENCES categories(id)\\n);\\n```", "Это концептуальный SQL-эскиз. Полная Room-схема позже добавит тип, дату и индексы. SQLite использует динамическую систему типов, но Room проверяет соответствие полей Entity ожидаемой схеме. Обратите внимание на `INTEGER PRIMARY KEY` и ссылку category_id.")
slide("INSERT: добавляем операцию", "```sql\\nINSERT INTO transactions\\n  (description, amount_minor, type, occurred_at)\\nVALUES ('Кофе', 25000, 'EXPENSE', 1791820800000);\\n```\\n\\nОдна команда добавляет одну строку и должна соблюдать ограничения.", "В реальном приложении значения передаются параметрами DAO, а не конкатенируются в строку SQL. Пример нужен для понимания результата. Если нарушить NOT NULL или внешний ключ, вставка должна завершиться ошибкой, а не породить некорректную запись.")
slide("SELECT: читаем историю", "```sql\\nSELECT id, description, amount_minor, type\\nFROM transactions\\nORDER BY occurred_at DESC, id DESC;\\n```\\n\\nЯвная сортировка обязательна для предсказуемого порядка.", "SQL не обещает порядок строк без ORDER BY. Вторичный ключ id помогает упорядочить операции с одинаковой отметкой времени. На экране истории обычно не нужен `SELECT *` из всех таблиц; выбирайте поля, нужные конкретному запросу.")
slide("WHERE: фильтр", "```sql\\nSELECT * FROM transactions\\nWHERE type = 'EXPENSE'\\n  AND amount_minor >= 100000;\\n```\\n\\nПокажет расходы от 1000 ₽.", "Поясните единицы: 100000 копеек — 1000 рублей. Условие `AND` требует выполнения обеих частей. Для фильтра по категории используйте `category_id = :categoryId`, где Room безопасно подставит значение аргумента.")
slide("UPDATE и DELETE", "```sql\\nUPDATE transactions\\nSET description = 'Обед'\\nWHERE id = 41;\\n\\nDELETE FROM transactions WHERE id = 41;\\n```\\n\\nБез `WHERE` изменятся или удалятся все строки таблицы.", "На этом слайде полезно остановиться: запрос без WHERE может затронуть всю таблицу. В Room методы `@Update` и `@Delete` работают с переданной Entity и её первичным ключом, что снижает риск случайного широкого изменения.")
slide("Агрегация: считаем баланс", "```sql\\nSELECT COALESCE(SUM(\\n  CASE WHEN type = 'INCOME'\\n       THEN amount_minor ELSE -amount_minor END\\n), 0) AS balance_minor\\nFROM transactions;\\n```", "SUM возвращает NULL, если подходящих строк нет, поэтому COALESCE превращает пустую базу в нулевой баланс. Доход прибавляется, расход вычитается. Проверяйте диапазон Long и единицы при выводе. Баланс можно вычислять запросом, не дублируя его в отдельной колонке состояния.")
slide("GROUP BY: расходы по категориям", "```sql\\nSELECT category_id, SUM(amount_minor) AS total_minor\\nFROM transactions\\nWHERE type = 'EXPENSE'\\nGROUP BY category_id;\\n```\\n\\nОдна строка результата на каждую категорию.", "Агрегация часто эффективнее, чем читать все операции в память и группировать в Kotlin. Для красивых названий категорий потребуется JOIN с categories. Если category_id может быть NULL, такие расходы попадут в отдельную группу без категории.")
slide("Параметры вместо сборки строки", "```kotlin\\n@Query(\"\"\"SELECT * FROM transactions\\n          WHERE category_id = :categoryId\"\"\")\\nfun byCategory(categoryId: Long): Flow<List<TransactionEntity>>\\n```\\n\\n`:categoryId` связывается с аргументом функции.", "В Room плейсхолдеры проверяются при компиляции и значения привязываются безопасно. Не собирайте SQL через `\"...\" + userInput`: это хрупко и открывает путь SQL-инъекциям. Для сортировки по произвольному столбцу нельзя напрямую параметризовать имя столбца; допустимые варианты выбирают явно.")

slide("JOIN: как читать круги", """- A — операции, B — категории.
- Пересечение — пары, для которых истинно условие `ON`.
- Закрашенная часть показывает состав результата, но не число строк.

```sql
SELECT t.id, c.name
FROM transactions t
LEFT JOIN categories c
ON c.id = t.category_id;
```""", """Круги Эйлера — учебная схема отбора совпавших и несовпавших строк. Она не показывает число строк результата: одной категории могут соответствовать десятки операций, поэтому одна строка B соединится с несколькими строками A. Также диаграмма не объясняет значения NULL и повторяющиеся строки. Всегда дополняйте её условием `ON` и маленьким примером данных. Для FinanceApp условие: `t.category_id = c.id`. [Описание обработки JOIN в SQLite](https://www.sqlite.org/lang_select.html).""")
visual("INNER JOIN: только совпадения", """Только операции с найденной категорией.

```sql
SELECT t.id, c.name
FROM transactions t
INNER JOIN categories c
ON c.id = t.category_id;
```""", """Запрос: `SELECT t.id, c.name FROM transactions AS t INNER JOIN categories AS c ON c.id = t.category_id;`. Покажите три операции, одна без категории, и две категории, одна без операций. INNER JOIN вернёт только совпавшие пары. Если две операции ссылаются на одну категорию, результат содержит две строки. Это важная граница круговой схемы: она показывает состав, но не количество. [SQLite SELECT](https://www.sqlite.org/lang_select.html).""", "join-inner.svg", "Закрашено пересечение A и B.")
visual("LEFT JOIN: все операции", """Все операции, даже без категории.

```sql
SELECT t.id, c.name
FROM transactions t
LEFT JOIN categories c
ON c.id = t.category_id;
```""", """Запрос: `SELECT t.id, c.name FROM transactions AS t LEFT JOIN categories AS c ON c.id = t.category_id;`. Даже операция с NULL category_id останется в истории. Для её categoryName результат даст NULL. Если добавить `WHERE c.name = 'Еда'`, строки без категории исчезнут: фильтр WHERE срабатывает после формирования внешнего соединения. Когда нужно сохранить все операции, условие на категорию иногда следует помещать в ON. [SQLite SELECT](https://www.sqlite.org/lang_select.html).""", "join-left.svg", "Закрашен весь левый круг A, включая пересечение.")
visual("RIGHT JOIN: все категории", """Все категории, даже без операций.

```sql
SELECT t.id, c.name
FROM transactions t
RIGHT JOIN categories c
ON c.id = t.category_id;
```""", """Запрос: `SELECT t.id, c.name FROM transactions AS t RIGHT JOIN categories AS c ON c.id = t.category_id;`. Для категории без покупок t.id будет NULL. Логически тот же набор можно получить перестановкой таблиц в `categories c LEFT JOIN transactions t`. Последний вариант лучше для совместимости с Android, потому что RIGHT JOIN появился в SQLite 3.39, а системная версия SQLite зависит от устройства. [SQLite 3.39 release](https://www.sqlite.org/releaselog/3_39_0.html).""", "join-right.svg", "Закрашен весь правый круг B, включая пересечение.")
visual("FULL OUTER JOIN: обе стороны", """Совпадения и несовпавшие строки обеих таблиц.

```sql
SELECT t.id, c.name
FROM transactions t
FULL JOIN categories c
ON c.id = t.category_id;
```""", """Запрос: `SELECT t.id, c.name FROM transactions AS t FULL OUTER JOIN categories AS c ON c.id = t.category_id;`. FULL JOIN объединяет эффект LEFT и RIGHT JOIN: сохраняет все несовпавшие строки с обеих сторон. Поддержка есть в SQLite с версии 3.39; системная SQLite на некоторых Android-устройствах может быть старее. Для учебного Android-примера основной рабочий запрос — LEFT JOIN, а FULL показываем для полноты картины. [SQLite SELECT](https://www.sqlite.org/lang_select.html), [SQLite 3.39 release](https://www.sqlite.org/releaselog/3_39_0.html).""", "join-full.svg", "Закрашены оба круга A и B.")
slide("CROSS JOIN: все комбинации", """Каждая операция соединяется с каждой категорией.

```sql
SELECT t.id, c.id
FROM transactions t
CROSS JOIN categories c;
```

3 операции × 4 категории = 12 строк.""", """CROSS JOIN строит декартово произведение, не сравнивая ключи. Это не способ получить названия категорий операций: для этого нужен JOIN с ON. Применяйте CROSS JOIN, когда действительно нужны все сочетания двух наборов, например наборы параметров отчёта. [SQLite SELECT](https://www.sqlite.org/lang_select.html).""")
slide("SELF JOIN: таблица с самой собой", """Ищем пары разных операций в одной категории.

```sql
SELECT a.id, b.id
FROM transactions a
JOIN transactions b
ON a.category_id = b.category_id
AND a.id < b.id;
```""", """SELF JOIN — не отдельный оператор SQL, а обычное соединение одной таблицы с самой собой под разными псевдонимами. `a.id < b.id` исключает пару записи с самой собой и не даёт дублировать пары в обратном порядке. Если category_id равен NULL, обычное сравнение не создаст пару. Круги Эйлера для INNER/OUTER JOIN здесь не объясняют выбор двух ролей одной таблицы. [SQLite SELECT](https://www.sqlite.org/lang_select.html).""")

section("Нормализация без лишней теории", "Что взять из статьи на Хабре и применить в FinanceApp")
slide("Почему возникает дублирование", "Плохая таблица: `операция | категория | цвет категории`.\\n\\nКатегория «Еда» и её цвет повторяются в каждой покупке.\\n\\nПри переименовании приходится менять много строк.", "Статья Сергея Сивкова на Хабре подробно разбирает нормальные формы. Для первого приложения достаточно уверенно понимать 1НФ, 2НФ и 3НФ и видеть аномалии. Используем собственный пример FinanceApp, а не копируем таблицы статьи. Источник: https://habr.com/ru/articles/254773/.")
slide("Аномалия обновления", "Было 30 операций с текстом категории «Продукты».\\n\\nКатегорию переименовали в «Еда», но обновили 29 строк.\\n\\nОдна сущность теперь имеет два названия.", "Аномалия обновления возникает, когда один факт хранится в нескольких местах. База не понимает, какое название верно. Выделение категории в отдельную таблицу решает именно эту проблему: название обновляется в одной строке.")
slide("Аномалии вставки и удаления", "- Вставка: нельзя создать категорию, пока нет операции, если всё в одной таблице.\\n- Удаление: удалили последнюю операцию и потеряли информацию о категории.\\n- Причина: смешали независимые сущности.", "Попросите привести пример категории «Путешествия», которую пользователь создал заранее. Если единственная таблица требует операцию, категорию отдельно сохранить негде. Аналогично удаление последней поездки не должно удалять саму категорию.")
slide("Первая нормальная форма", "**1НФ:** каждое поле хранит одно значение своего домена, а строка однозначно различима.\\n\\nПлохо: `tags = 'еда, дом, семья'`.\\n\\nЛучше: отдельные строки таблицы связей.", "В учебном объяснении акцентируйте атомарность относительно задач приложения. Если по тегам нужно искать и ставить ограничения, CSV-строка мешает. Не утверждайте, что любой текст с запятыми нарушает 1НФ: адрес или комментарий могут быть единым значением для данной модели. См. https://habr.com/ru/articles/254773/.")
slide("Вторая нормальная форма", "**2НФ:** таблица уже в 1НФ, а неключевые поля зависят от полного кандидатного ключа.\\n\\nАктуально для составного ключа `(transaction_id, tag_id)`: название тега зависит лишь от `tag_id`.", "Если таблица transaction_tags с составным ключом хранит ещё и tag_name, название зависит от части ключа, а не от пары целиком. Перенесите tag_name в tags. При одиночном суррогатном ключе частичная зависимость по такому ключу не возникает, но это не освобождает от анализа естественных зависимостей и 3НФ.")
slide("Третья нормальная форма", "**3НФ:** неключевой факт не должен зависеть от ключа через другой неключевой факт.\\n\\n`transaction_id → category_id → category_name`\\n\\nЗначит, `category_name` хранится в `categories`.", "Формально 3НФ определяется через функциональные зависимости и потенциальные ключи. Для первого знакомства полезна практическая эвристика: факт о категории живёт в таблице категорий, факт об операции в таблице операций. Покажите цепочку зависимости и вернитесь к аномалии обновления.")
slide("Декомпозиция нашей схемы", "`categories(id, name, color)`\\n`transactions(id, description, amount_minor, type, occurred_at, category_id)`\\n\\nСвязь восстанавливается через `JOIN` по `category_id`.", "Разделение таблиц не должно терять информацию. Внешний ключ сохраняет связь, JOIN собирает нужное представление для экрана. Нормализация добавляет необходимость соединений, но уменьшает дублирование и аномалии. Это осознанный обмен, а не правило «как можно больше таблиц».")
slide("Когда не стоит дробить дальше", "- 4НФ и 5НФ решают более редкие многозначные зависимости и зависимости соединения.\\n- Для FinanceApp сейчас достаточно 3НФ.\\n- Дополнительное разбиение оправдывают конкретные аномалии и запросы.", "Статья на Хабре рассматривает формы до 6НФ и доменно-ключевой. Упомяните их как продолжение, но не заставляйте запоминать формальные определения за одну пару. Практическая цель — корректно отделить категории от операций и не хранить списки значений в одной ячейке.")

section("SQLite и Room в Android", "Библиотека поверх реляционной базы")
slide("Почему Room", "Room добавляет поверх SQLite:\\n\\n- проверку SQL-запросов при компиляции;\\n- аннотации вместо ручного однотипного кода;\\n- поддержку миграций и наблюдаемых запросов.", "По официальной документации Android Room рекомендуется вместо прямого использования SQLite API для типового локального хранилища. Он не отменяет проектирование схемы и знание SQL. При ошибке имени таблицы в `@Query` сборка обычно останавливается, что удобнее позднего сбоя на устройстве. https://developer.android.com/training/data-storage/room.")
slide("Три основных компонента", "- `@Entity` описывает таблицу и строки.\\n- `@Dao` описывает операции доступа.\\n- `@Database` связывает Entity и DAO и задаёт версию схемы.\\n\\n`Room.databaseBuilder` создаёт экземпляр базы.", "Покажите путь от UI: экран вызывает ViewModel, ViewModel использует Repository, Repository обращается к DAO, DAO работает с SQLite через Room. Схема задаётся Entity и классом Database. Это не четыре независимые базы, а четыре роли в коде.")
slide("Версия примеров на лекции", "Примеры используют **Room 3.0.3** и пакет `androidx.room3`.\\n\\nRoom 3 требует Kotlin + KSP; одноразовые DAO-операции объявляются `suspend`, наблюдаемые чтения могут возвращать `Flow`.", "На 26 октября 2026 года стабильная версия Room 3 — 3.0.3. Она отличается от Room 2.x по координатам Gradle и импортам. При использовании старого проекта на Room 2 нельзя механически смешивать пакеты `androidx.room` и `androidx.room3`; нужна отдельная миграция библиотеки. Версии и требования: https://developer.android.com/jetpack/androidx/releases/room3 и https://developer.android.com/training/data-storage/room/migration-2-to-3.")
slide("Gradle: зависимости", "```kotlin\\nplugins {\\n    id(\"com.google.devtools.ksp\")\\n}\\n\\ndependencies {\\n    val roomVersion = \"3.0.3\"\\n    implementation(\"androidx.room3:room3-runtime:$roomVersion\")\\n    ksp(\"androidx.room3:room3-compiler:$roomVersion\")\\n}\\n```", "KSP-плагин должен иметь версию, совместимую с версией Kotlin в проекте; в реальном проекте её задают в корневом Gradle или version catalog. Не придумывайте произвольный номер KSP на слайде. Убедитесь, что подключён Google Maven. Для `AndroidSQLiteDriver` показана зависимость `sqlite-framework`; для `Flow` отдельный артефакт Room не требуется.")
slide("Почему нужен KSP", "- Room читает аннотации во время сборки.\\n- Генерирует реализации Database и DAO.\\n- Проверяет SQL, типы результатов и соответствие колонок.\\n- Ошибка схемы становится ошибкой сборки.", "KSP — Kotlin Symbol Processing. Студенты не пишут вручную реализацию интерфейса DAO: её генерирует компилятор Room. После добавления аннотаций следует выполнить Gradle Sync и сборку, чтобы увидеть диагностику. Room 3 не использует kapt или Java annotation processor для генерации.")
slide("Entity и таблица", "```kotlin\\n@Entity(tableName = \"transactions\")\\ndata class TransactionEntity(\\n    @PrimaryKey(autoGenerate = true) val id: Long = 0,\\n    val description: String,\\n    @ColumnInfo(name = \"amount_minor\") val amountMinor: Long,\\n    val type: String,\\n    @ColumnInfo(name = \"occurred_at\") val occurredAt: Long,\\n)\\n```", "Импорты берутся из `androidx.room3`. `autoGenerate` поручает базе назначить id при вставке новой записи; значение 0 служит учебным признаком новой Entity. `amountMinor` в Kotlin отображается в столбец amount_minor. Таблица называется transactions независимо от имени класса. Источник: https://developer.android.com/training/data-storage/room/defining-data.")
slide("Nullable и типы полей", "- `String` соответствует обязательному тексту.\\n- `String?` допускает отсутствие значения.\\n- `Long` подходит для суммы в копейках и timestamp.\\n- Для сложного типа может понадобиться преобразователь.", "Связь Kotlin nullability и схемы помогает заранее видеть ограничения. Значение Long не делает сумму автоматически положительной: это отдельный инвариант приложения. Для даты можно хранить epoch milliseconds в Long; `Date` потребует converter. Room 3 также умеет базовое преобразование enum, но строковое поле на первых шагах прозрачнее.")
slide("Категория как вторая Entity", "```kotlin\\n@Entity(tableName = \"categories\")\\ndata class CategoryEntity(\\n    @PrimaryKey(autoGenerate = true) val id: Long = 0,\\n    val name: String,\\n    val colorArgb: Long,\\n)\\n```\\n\\nНазвание категории хранится отдельно от операций.", "Это прямое воплощение нормализации предыдущего раздела. Для запрета дублей названий можно добавить уникальный индекс и решить вопрос регистра и пробелов. Не смешивайте цвет UI и неизменный факт предметной области: цвет категории здесь пользовательская настройка.")

section("DAO и создание базы", "От аннотаций к работающему хранилищу")
slide("DAO: граница SQL-доступа", "```kotlin\\n@Dao\\ninterface TransactionDao {\\n    @Insert\\n    suspend fun insert(item: TransactionEntity): Long\\n\\n    @Query(\"SELECT * FROM transactions ORDER BY occurred_at DESC, id DESC\")\\n    fun observeAll(): Flow<List<TransactionEntity>>\\n}\\n```", "`@Dao` сообщает Room, что интерфейс описывает доступ к данным. `insert` — одноразовая операция записи, поэтому в Room 3 она suspend. `observeAll` возвращает Flow и будет отдавать новый список при изменении затронутой таблицы. Импорты `Flow` из kotlinx.coroutines.flow и аннотаций из androidx.room3.")
slide("DAO: чтение одной записи", "```kotlin\\n@Query(\"SELECT * FROM transactions WHERE id = :id LIMIT 1\")\\nsuspend fun findById(id: Long): TransactionEntity?\\n```\\n\\n`null` означает, что строка с таким id отсутствует.", "Одноразовый снимок удобно получить suspend-функцией. `LIMIT 1` подчёркивает ожидание одной строки. Первичный ключ уже обеспечивает уникальность, но ограничение делает намерение читаемым. Не используйте невозвратный тип, если отсутствие записи нормально для сценария.")
slide("DAO: изменение и удаление", "```kotlin\\n@Update\\nsuspend fun update(item: TransactionEntity)\\n\\n@Delete\\nsuspend fun delete(item: TransactionEntity)\\n```\\n\\nRoom находит строку по первичному ключу Entity.", "Перед обновлением объект должен иметь id существующей строки. Если важен факт успешного удаления или изменения, Room может возвращать количество затронутых строк; это полезно для обработки гонок и устаревшего UI. `@Update` не заменяет правила валидации суммы.")
slide("DAO: фильтр и баланс", "```kotlin\\n@Query(\"SELECT * FROM transactions WHERE type = :type ORDER BY occurred_at DESC\")\\nfun observeByType(type: String): Flow<List<TransactionEntity>>\\n\\n@Query(\"SELECT COALESCE(SUM(CASE WHEN type = 'INCOME' THEN amount_minor ELSE -amount_minor END), 0) FROM transactions\")\\nfun observeBalance(): Flow<Long>\\n```", "Room проверяет имена таблиц и колонок при сборке. Flow подходит, когда экран должен автоматически обновиться после вставки или удаления. Для большого приложения фильтры можно собрать в отдельные запросы или управляемую модель параметров, но не через конкатенацию пользовательского ввода в SQL.")
slide("Database связывает части", "```kotlin\\n@Database(\\n    entities = [TransactionEntity::class, CategoryEntity::class],\\n    version = 1,\\n)\\nabstract class AppDatabase : RoomDatabase() {\\n    abstract fun transactionDao(): TransactionDao\\n    abstract fun categoryDao(): CategoryDao\\n}\\n```", "При добавлении CategoryEntity нужен реальный CategoryDao или можно временно оставить только метод transactionDao; на слайде показана полная целевая конфигурация. `version = 1` — версия схемы базы, а не версия приложения. При изменении схемы её увеличивают и определяют путь миграции. Источник: https://developer.android.com/training/data-storage/room.")
slide("Создаём экземпляр базы", "```kotlin\\nval db = Room.databaseBuilder<AppDatabase>(\\n    applicationContext, \"finance.db\"\\n).setDriver(AndroidSQLiteDriver()).build()\\n\\nval dao = db.transactionDao()\\n```", "Официальный пример Room 3 использует generic builder и AndroidSQLiteDriver. Импорты: `androidx.room3.Room` и `androidx.sqlite.driver.AndroidSQLiteDriver`. Используйте applicationContext, чтобы база не удерживала Activity. Создание экземпляра относительно дорого, поэтому в однопроцессном приложении держите один экземпляр на всё приложение.")
slide("Один экземпляр на приложение", "```kotlin\\nobject DatabaseProvider {\\n    @Volatile private var instance: AppDatabase? = null\\n\\n    fun get(context: Context): AppDatabase =\\n        instance ?: synchronized(this) {\\n            instance ?: Room.databaseBuilder<AppDatabase>(\\n                context.applicationContext, \"finance.db\"\\n            ).setDriver(AndroidSQLiteDriver()).build()\\n                .also { instance = it }\\n        }\\n}\\n```", "Это один из способов ленивого singleton для учебного проекта. В приложении с DI экземпляр удобно предоставлять через контейнер зависимостей. Синхронизация нужна, чтобы два потока не построили два экземпляра одновременно. Не создавайте базу при каждой рекомпозиции или нажатии кнопки.")
slide("Порядок первой сборки", "1. Подключить KSP и Room runtime/compiler.\\n2. Создать Entity.\\n3. Создать DAO.\\n4. Создать `AppDatabase`.\\n5. Синхронизировать Gradle и собрать проект.\\n6. Создать базу через builder и выполнить запрос.", "Покажите студентам, что ошибка имени таблицы в `@Query` должна проявиться на шаге сборки. Для целостного минимального примера можно сначала создать только TransactionEntity и TransactionDao, а категорию добавить вторым этапом. Это снижает число одновременных ошибок при живом кодинге.")
slide("Что именно создаётся на устройстве", "- `finance.db` — файл базы в приватном хранилище приложения.\\n- Таблицы создаются при первом открытии базы.\\n- Установка новой версии приложения сохраняет данные, если не очищать хранилище.\\n- Смена схемы требует миграции.", "`build()` создаёт объект RoomDatabase, а фактическое открытие и создание файла может произойти при первом обращении. При удалении приложения или очистке данных локальная база обычно удаляется. В Android Studio можно открыть Database Inspector и посмотреть таблицы на эмуляторе.")

section("Связи и наблюдаемые данные", "Категории, Flow и экран Compose")
slide("Добавляем внешний ключ в Entity", "```kotlin\\n@Entity(\\n    tableName = \"transactions\",\\n    foreignKeys = [ForeignKey(\\n        entity = CategoryEntity::class,\\n        parentColumns = [\"id\"], childColumns = [\"category_id\"],\\n        onDelete = ForeignKey.SET_NULL,\\n    )],\\n    indices = [Index(\"category_id\")],\\n)\\ndata class TransactionEntity(\\n    @PrimaryKey(autoGenerate = true) val id: Long = 0,\\n    @ColumnInfo(name = \"category_id\") val categoryId: Long?,\\n    // остальные поля показаны ранее\\n)\\n```", "Это фрагмент расширенной Entity, а не отдельный полный класс для копирования. `SET_NULL` согласуется с nullable categoryId: после удаления категории операция остаётся без категории. Индекс на дочернем ключе помогает запросам и операциям изменения родителя. Для приложения, где удалять использованную категорию нельзя, выбрали бы RESTRICT.")
slide("Room не хранит вложенную Entity", "`TransactionEntity` хранит `categoryId`, а не поле `CategoryEntity`.\\n\\nДля экрана данные соединяются запросом или специальной моделью отношения.", "В отличие от некоторых ORM, Room не разрешает прямые объектные ссылки между Entity. Это делает стоимость загрузки данных явной и избегает скрытых запросов. Ссылка на категорию выражается ключом, а не графом объектов. https://developer.android.com/training/data-storage/room/relationships.")
slide("JOIN-проекция для экрана", "```kotlin\\ndata class TransactionRow(\\n    val id: Long,\\n    val description: String,\\n    val categoryName: String?,\\n)\\n\\n@Query(\"\"\"SELECT t.id, t.description, c.name AS categoryName\\n          FROM transactions t LEFT JOIN categories c\\n          ON c.id = t.category_id\"\"\")\\nfun observeRows(): Flow<List<TransactionRow>>\\n```", "SQL-алиас categoryName должен соответствовать свойству DTO. `LEFT JOIN` сохраняет операции с categoryId NULL. Проекция полезна, когда UI нужна объединённая строка, но не все поля обеих таблиц. Добавьте ORDER BY для реального экрана истории; здесь акцент на соединении.")
slide("Flow — наблюдаемый запрос", "- `Flow<List<TransactionEntity>>` подписывается на результат.\\n- Сначала выдаёт текущие строки.\\n- При изменении таблицы Room выполняет запрос снова и выдаёт новый результат.\\n- Экран получает актуальную историю без ручного `reload()`.", "Flow холодный: пока нет коллектора, чтение не выполняется. Room отслеживает инвалидирование таблиц и повторно выдаёт результат при изменениях. Избегайте формулировки «каждая запись мгновенно пушится»: Room заново вычисляет результат запроса и обновление зависит от коллектора и планировщика.")
slide("Repository отделяет хранение", "```kotlin\\nclass TransactionRepository(private val dao: TransactionDao) {\\n    val transactions = dao.observeAll()\\n    val balance = dao.observeBalance()\\n\\n    suspend fun add(item: TransactionEntity): Long = dao.insert(item)\\n    suspend fun remove(item: TransactionEntity) = dao.delete(item)\\n}\\n```", "Repository задаёт понятный API для ViewModel и скрывает подробности DAO. Для учебного проекта он тонкий, это нормально. Позже в этом месте можно объединить локальную базу и сеть, не заставляя UI знать, откуда пришли данные. Валидацию описания и суммы можно выполнить до создания Entity.")
slide("ViewModel читает и записывает", "```kotlin\\nclass TransactionViewModel(\\n    private val repo: TransactionRepository\\n) : ViewModel() {\\n    val transactions = repo.transactions\\n        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())\\n\\n    fun add(item: TransactionEntity) = viewModelScope.launch {\\n        repo.add(item)\\n    }\\n}\\n```", "`stateIn` превращает Flow репозитория в StateFlow, удерживаемый ViewModel. Для упрощения на слайде показан один поток, но баланс можно подключить аналогично или объединить через combine в единый UiState. `viewModelScope.launch` не блокирует UI. Конструктор с параметром требует фабрики ViewModel или DI, простого `viewModel()` без фабрики уже недостаточно.")
slide("Compose собирает состояние", "```kotlin\\n@Composable\\nfun TransactionScreen(vm: TransactionViewModel) {\\n    val items by vm.transactions.collectAsStateWithLifecycle()\\n    LazyColumn {\\n        items(items, key = { it.id }) { item ->\\n            Text(item.description)\\n        }\\n    }\\n}\\n```", "Для `collectAsStateWithLifecycle` нужна зависимость `androidx.lifecycle:lifecycle-runtime-compose`. `key = { it.id }` помогает Compose сохранять состояние элементов списка при изменении порядка. Передача готовой ViewModel в экран — учебный вариант; в более крупном приложении удобнее разделить route и stateless content.")
slide("Поток данных после вставки", "`Кнопка → ViewModel → Repository → DAO → SQLite`\\n\\n`SQLite → Flow DAO → StateFlow ViewModel → Compose`\\n\\nБаланс и история исходят из сохранённых данных.", "Проследите одну операцию целиком. ViewModel сначала проверяет ввод, запускает suspend-вставку, Room меняет таблицу, наблюдаемый запрос пересчитывается, Compose получает новый список. Если UI отдельно добавляет элемент в список до успешной вставки, возможен рассинхрон; для простого примера пусть источник истины — база.")

section("Надёжность и развитие схемы", "Транзакции, индексы, миграции, проверки")
slide("Транзакция БД", "Транзакция объединяет несколько изменений в одну атомарную операцию: либо применяются все, либо ни одно.\\n\\nПример: добавить перевод между счетами и изменить оба остатка.", "Слово «транзакция» здесь имеет два смысла: финансовая операция FinanceApp и транзакция SQLite. Проговорите различие. Для добавления одной строки отдельная ручная транзакция не нужна. Для связанных изменений, например запись расхода и обновление отдельного счёта, атомарность уже критична.")
slide("`@Transaction` в DAO", "```kotlin\\n@Dao\\ninterface TransferDao {\\n    @Insert suspend fun insertTransfer(item: TransferEntity)\\n    @Query(\"UPDATE accounts SET balance_minor = balance_minor + :delta WHERE id = :id\")\\n    suspend fun changeBalance(id: Long, delta: Long)\\n\\n    @Transaction\\n    suspend fun transfer(item: TransferEntity) {\\n        changeBalance(item.fromId, -item.amountMinor)\\n        changeBalance(item.toId, item.amountMinor)\\n        insertTransfer(item)\\n    }\\n}\\n```", "Это концептуальный пример, предполагающий объявленные AccountEntity и TransferEntity. `@Transaction` защищает группу шагов от частичного применения. До вызова нужно проверить положительную сумму и наличие обоих счетов; обновление 0 строк следует считать ошибкой, иначе можно записать перевод без реального движения денег.")
slide("Индекс: зачем он", "Индекс ускоряет поиск и сортировку по выбранным колонкам.\\n\\nДля истории по категории и времени полезен индекс `(category_id, occurred_at)`.\\n\\nЦена индекса: место на диске и работа при каждой записи.", "Не добавляйте индекс на каждое поле. Сначала назовите частый запрос, затем проверьте план и объём данных. Индекс по внешнему ключу обычно особенно уместен. Room описывает индексы через `@Entity(indices = [Index(...)])`.")
slide("Версия схемы", "`@Database(version = 1)` фиксирует первую схему.\\n\\nКогда добавляем столбец или таблицу, версия становится 2.\\n\\nСтарая база на устройстве должна быть приведена к новой схеме.", "Версия приложения в Play и версия схемы Room не обязаны совпадать. Если просто поднять число версии и не предоставить путь миграции, существующее приложение может не открыть базу. Новая установка с нуля может работать, поэтому проверять нужно именно обновление старой версии.")
slide("Пример изменения: заметка к операции", "Версия 1: `description, amount_minor, type, occurred_at`.\\n\\nВерсия 2: добавляем `note TEXT NOT NULL DEFAULT ''`.\\n\\nЗначение по умолчанию нужно для старых строк.", "Перед миграцией продумайте существующие данные. Новый NOT NULL столбец без default нельзя корректно добавить к строкам, которые уже лежат в базе. Если заметка необязательна, можно выбрать nullable столбец, но это изменит Kotlin-модель и UI.")
slide("Ручная миграция 1 → 2", "```kotlin\\nval MIGRATION_1_2 = object : Migration(1, 2) {\\n    override suspend fun migrate(connection: SQLiteConnection) {\\n        connection.executeSQL(\\n            \"ALTER TABLE transactions ADD COLUMN note TEXT NOT NULL DEFAULT ''\"\\n        )\\n    }\\n}\\n\\nRoom.databaseBuilder<AppDatabase>(context, \"finance.db\")\\n    .setDriver(AndroidSQLiteDriver())\\n    .addMigrations(MIGRATION_1_2).build()\\n```", "В Room 3 метод migrate является suspend и получает SQLiteConnection. В лекции это фрагмент: новая Entity также должна иметь поле note, а версия Database — 2. При сборке и открытии Room проверит итоговую схему. Источник: https://developer.android.com/training/data-storage/room/migrating-db-versions.")
slide("Автоматическая миграция", "Для простого изменения Room может сгенерировать переход через `@AutoMigration(from = 1, to = 2)`.\\n\\nНужны экспортированные схемы обеих версий. Переименование или удаление неоднозначно и требует `AutoMigrationSpec` либо ручной миграции.", "Автоматическая миграция не означает, что не надо думать о старых данных. Храните JSON-схемы в Git и запускайте тесты переходов. Для первого объяснения достаточно разобрать ручное добавление одного столбца как явный SQL-переход.")
slide("Опасность destructive fallback", "`fallbackToDestructiveMigration()` пересоздаёт таблицы при отсутствии пути миграции.\\n\\nДля пользовательской истории расходов это означает потерю записей.\\n\\nВ учебном черновике допустимо только при осознанном согласии на потерю данных.", "Эту настройку часто копируют из коротких туториалов, потому что она быстро устраняет ошибку несовпадения схем. Для финансового приложения она опасна. Лучше настроить миграцию, экспорт схем и тест обновления. Официальная документация прямо предупреждает об удалении данных при fallback.")
slide("Как проверить миграцию", "1. Установить версию 1 и создать записи.\\n2. Обновить APK до версии 2 без очистки данных.\\n3. Проверить старые записи и новое поле.\\n4. Автоматизировать через `MigrationTestHelper` и схемы в Git.", "Сборка новой версии на чистом эмуляторе не проверяет миграцию. В тесте должен реально существовать старый файл базы. Для Room 3 доступен артефакт `room3-testing`, а экспортированные схемы нужны для воспроизведения предыдущих версий. https://developer.android.com/training/data-storage/room/migrating-db-versions.")
slide("Что проверять у DAO", "- Вставка возвращает id и запись читается по нему.\\n- Пустая база даёт баланс 0.\\n- Доход и расход меняют баланс с разным знаком.\\n- Удаление обновляет Flow.\\n- Связь с категорией не теряет операции без категории.", "Это поведенческие проверки, а не повторение внутреннего кода DAO. Используйте тестовую базу в памяти для быстрых изолированных тестов, а миграции проверяйте отдельно на файле старой схемы. Учитывайте, что эмиссия Flow асинхронна и тест должен дождаться ожидаемого значения.")

section("Итоги и источники", "Главные идеи о SQL и Room")
slide("Что запомнить", "- База хранит записи дольше жизни процесса.\\n- Ключи и связи задают целостность.\\n- SQL описывает нужный результат.\\n- 1НФ–3НФ помогают убрать аномалии.\\n- Room связывает Entity, DAO и Database.\\n- Flow передаёт изменения в ViewModel и Compose.", "Вернитесь к исходной проблеме FinanceApp: история исчезала после завершения процесса. Теперь цепочка от пользовательского действия до файла SQLite и обратно объясняет, почему данные остаются. Попросите студента нарисовать цепочку без подсказки.")
slide("Источники и продолжение", "- [Нормальные формы: Хабр](https://habr.com/ru/articles/254773/).\n- [Пять групп SQL-команд](https://www.geeksforgeeks.org/sql/sql-ddl-dql-dml-dcl-tcl-commands/).\n- [JOIN и SELECT в SQLite](https://www.sqlite.org/lang_select.html).\n- [Room: официальный обзор](https://developer.android.com/training/data-storage/room).\n- [Entity в Room](https://developer.android.com/training/data-storage/room/defining-data).", "Статья на Хабре использована как отправная точка раздела нормализации, примеры слайдов переработаны под FinanceApp. Классификация DDL/DQL/DML/DCL/TCL взята из указанного материала GeeksforGeeks, а точная семантика JOIN сверена с документацией SQLite. Для кода Room приоритет отдан официальной документации Android, актуальной на 26 октября 2026 года. Следующая лекция курса — компоненты Android.")

